import AppKit
import os

enum PasteboardBridge {
  private static let concealed = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
  ]
  private static let logger = Logger(subsystem: "local.devbar.app", category: "web")

  static func readText() -> String {
    let board = NSPasteboard.general
    let count = board.changeCount
    let types = board.types ?? []
    if types.contains(where: { concealed.contains($0.rawValue) }) {
      return #"{"status":"concealed"}"#
    }
    switch board.accessBehavior {
    case .alwaysDeny: return #"{"status":"denied"}"#
    case .alwaysAllow: break
    default: return #"{"status":"ask"}"#
    }
    guard types.contains(where: { $0 == .string }) else {
      return types.isEmpty ? #"{"status":"empty"}"# : #"{"status":"notText"}"#
    }
    guard let text = board.string(forType: .string) else {
      return #"{"status":"empty"}"#
    }
    guard board.changeCount == count else { return #"{"status":"empty"}"# }
    logger.notice("clipboardRead bytes=\(text.utf8.count, privacy: .public)")
    return #"{"status":"ok","text":"# + BridgeJSON.quoted(text) + "}"
  }

  static func writeText(_ text: String) {
    let board = NSPasteboard.general
    board.clearContents()
    board.setString(text, forType: .string)
    logger.notice("clipboardWrite bytes=\(text.utf8.count, privacy: .public)")
  }

  static func writePNGBase64(_ encoded: String) {
    guard let data = Data(base64Encoded: encoded) else { return }
    writePNG(data, file: nil)
  }

  static func writePNG(_ data: Data, file: URL?) {
    let board = NSPasteboard.general
    board.clearContents()
    let item = NSPasteboardItem()
    item.setData(data, forType: .png)
    if let file { item.setString(file.absoluteString, forType: .fileURL) }
    board.writeObjects([item])
    logger.notice("clipboardWriteImage bytes=\(data.count, privacy: .public)")
  }
}
